modelica_source:
model Baseline
  extends Modelica.Electrical.Analog.Examples.OpAmps.Multivibrator;
end Baseline;
model FINDING00868
  extends Modelica.Electrical.Analog.Examples.OpAmps.Multivibrator(R=0);
end FINDING00868;
model FINDING00866
  extends Modelica.Electrical.Analog.Examples.OpAmps.Multivibrator(R1=0);
end FINDING00866;
model FINDING00867
  extends Modelica.Electrical.Analog.Examples.OpAmps.Multivibrator(R2=0);
end FINDING00867;
model FINDING00874
  extends Modelica.Electrical.Analog.Examples.OpAmps.Multivibrator(f=0);
end FINDING00874;
model FinalFINDING00868
  extends Modelica.Electrical.Analog.Examples.OpAmps.Multivibrator(final R=0);
end FinalFINDING00868;
model FinalFINDING00866
  extends Modelica.Electrical.Analog.Examples.OpAmps.Multivibrator(final R1=0);
end FinalFINDING00866;
model FinalFINDING00867
  extends Modelica.Electrical.Analog.Examples.OpAmps.Multivibrator(final R2=0);
end FinalFINDING00867;
model FinalFINDING00874
  extends Modelica.Electrical.Analog.Examples.OpAmps.Multivibrator(final f=0);
end FinalFINDING00874;

mos:
setCommandLineOptions("--numProcs=1 --evaluateFinalParameters=true");
setCompiler("gcc");
setCXXCompiler("g++");
loadFile("/data/mrumoca/rumoca/target/corpus/ModelicaStandardLibrary-4.1.0/Modelica/package.mo");
loadFile("/data/mrumoca/rumoca/target/corpus/ModelicaStandardLibrary-4.1.0/ModelicaTest/package.mo");
loadFile("Cases.mo");
getErrorString();
print("AUDIT_CASE Baseline\n");
simulate(Baseline, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FINDING00868\n");
simulate(FINDING00868, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FINDING00866\n");
simulate(FINDING00866, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FINDING00867\n");
simulate(FINDING00867, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FINDING00874\n");
simulate(FINDING00874, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalFINDING00868\n");
simulate(FinalFINDING00868, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalFINDING00866\n");
simulate(FinalFINDING00866, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalFINDING00867\n");
simulate(FinalFINDING00867, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalFINDING00874\n");
simulate(FinalFINDING00874, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_OVERRIDE FINDING00868\n");
system("./Baseline -override R=0 -r=FINDING00868_override.csv");
print("AUDIT_OVERRIDE FINDING00866\n");
system("./Baseline -override R1=0 -r=FINDING00866_override.csv");
print("AUDIT_OVERRIDE FINDING00867\n");
system("./Baseline -override R2=0 -r=FINDING00867_override.csv");
print("AUDIT_OVERRIDE FINDING00874\n");
system("./Baseline -override f=0 -r=FINDING00874_override.csv");
